import { beforeEach } from 'vitest';
import '@testing-library/jest-dom/vitest';

beforeEach(() => {
  if (typeof document === 'undefined') {
    return;
  }
  // reset dom before each test
  const html = document.getElementsByTagName('html')[0];
  if (html) {
    html.innerHTML = '';
  }
});

import { track } from '@vercel/analytics/server';
import type { NextFetchEvent, NextRequest } from 'next/server';

export const config = {
  runtime: 'edge',
};

async function handler(_request: NextRequest, _event: NextFetchEvent) {
  track('Pages Api Route', {
    runtime: 'edge',
    router: 'pages',
  });

  return new Response('OK');
}

export default handler;

import { NextRequest } from 'next/server';
import GET from './test';

describe('pages API edge route', () => {
  const log = jest.spyOn(console, 'log').mockImplementation(() => void 0);

  beforeEach(() => jest.clearAllMocks());

  it('tracks event', async () => {
    const request = new NextRequest(new URL('/', 'http://localhost'));
    // @ts-expect-error -- we should pass a NextFetchEvent instead an empty object, but it's not used.
    const response = await GET(request, {});
    expect(response.status).toBe(200);
    expect(log).toHaveBeenCalledTimes(1);
    expect(log).toHaveBeenCalledWith(
      '[Vercel Web Analytics] Track "Pages Api Route" with data {"runtime":"edge","router":"pages"}',
    );
  });
});

import { beforeEach, describe, expect, it, vi } from 'vitest';
import { track } from './index';

describe('server track in browser environment', () => {
  global.fetch = vi.fn();
  const fetchMock = vi.mocked(global.fetch);

  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('throws error in development mode', async () => {
    (global as { window?: { vam?: string } }).window = { vam: 'development' };

    await expect(track('test-event')).rejects.toThrow(
      /imported the `track` function from `@vercel\/web-analytics\/server` in a browser environment/,
    );
  });

  it('returns early in production mode', async () => {
    (global as { window?: object }).window = {};

    await track('test-event');

    expect(fetchMock).not.toHaveBeenCalled();
  });
});

